import test from 'node:test';import assert from 'node:assert/strict';import {HARMONY_DEFAULTS,normalizeHarmony,harmonizePattern,harmonizeLane,linkHarmony} from './harmony.js';import {SCALES} from './poly-arp.js';
function state(root=36){return {root,steps:8,pattern:0,patterns:[Array.from({length:64},(_,i)=>({note:i%12,on:true,gate:.8}))]}}
test('harmonizes mono/acid/texture to the same key without changing rhythm',()=>{
 const h={key:2,scale:'DORIAN',degree:1};for(const [type,root] of [['mono',36],['acid',48],['texture',60]]){let v=state(root);let original=v.patterns[0].map(n=>({on:n.on,gate:n.gate}));assert.ok(harmonizePattern(v,type,h));assert.equal(v.root,{mono:26,acid:38,texture:50}[type]);for(let i=0;i<8;i++){const n=v.root+v.patterns[0][i].note;assert.ok(SCALES.DORIAN.includes(((n-2)%12+12)%12));assert.deepEqual({on:v.patterns[0][i].on,gate:v.patterns[0][i].gate},original[i]);}}
});
test('drums and external MIDI are not transposed',()=>{const drum={target:'DRUM MACHINE',steps:[{note:36,on:true}]};const ext={target:'MIDI OUT',steps:[{note:42,on:true}]};assert.equal(harmonizeLane(drum,{}),false);assert.equal(harmonizeLane(ext,{}),false);assert.equal(drum.steps[0].note,36);assert.equal(ext.steps[0].note,42)});
test('other conductor lanes quantize without mutating rests',()=>{const lane={target:'MONO',steps:Array.from({length:16},(_,i)=>({on:i%2===0,note:31,gate:.4,velocity:100}))};harmonizeLane(lane,{key:5,scale:'MAJOR'}, {generate:false});for(let i=0;i<16;i++){if(i%2===1)assert.equal(lane.steps[i].note,31);else assert.ok(SCALES.MAJOR.includes(((lane.steps[i].note-5)%12+12)%12))}});
test('Poly key and scale are applied to all synth states',()=>{const m={state:state()},p={state:{polyArp:{key:0,scale:'MINOR'}}},t={state:state()},a={state:state()};let x=linkHarmony({mono:m,poly:p,texture:t,acid:a},{key:4,scale:'MINOR',degree:2});assert.deepEqual(x,['POLY','MONO','TEXTURE','ACID']);assert.equal(p.state.polyArp.key,4);assert.equal(m.state.root,28)});
test('invalid key and scale normalize safely',()=>{assert.deepEqual(normalizeHarmony({key:99,scale:'unknown'}),{key:11,scale:'MINOR',degree:0,autoLink:true});});
